package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class MappingIterator_hasNextValue_TriageGen0Test {

    @Mock
    private JsonParser mockParser;

    private MappingIterator<Object> iterator;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // MappingIterator is usually created via ObjectMapper, 
        // but since we are testing a specific method with internal state, 
        // we will use reflection to inject the private fields.
        iterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));

        setInternalState(iterator, "_parser", mockParser);
        setInternalState(iterator, "_hasNextChecked", false);
        setInternalState(iterator, "_closeParser", false);
    }

    private void setInternalState(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testHasNextValue_ParserIsNull() throws IOException {
        setInternalState(iterator, "_parser", null);
        assertFalse(iterator.hasNextValue());
    }

    @Test
    public void testHasNextValue_AlreadyChecked() throws IOException {
        setInternalState(iterator, "_hasNextChecked", true);
        // If already checked, it should return true immediately (assuming parser is not null)
        assertTrue(iterator.hasNextValue());
    }

    @Test
    public void testHasNextValue_FirstTime_TokenNotNull() throws IOException {
        setInternalState(iterator, "_hasNextChecked", false);
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        assertTrue(iterator.hasNextValue());
        assertEquals(true, getInternalState(iterator, "_hasNextChecked"));
    }

    @Test
    public void testHasNextValue_FirstTime_TokenIsNull_NextTokenFound() throws IOException {
        setInternalState(iterator, "_hasNextChecked", false);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        assertTrue(iterator.hasNextValue());
        assertEquals(true, getInternalState(iterator, "_hasNextChecked"));
    }

    @Test
    public void testHasNextValue_FirstTime_TokenIsNull_NextTokenIsEndArray() throws IOException {
        setInternalState(iterator, "_hasNextChecked", false);
        setInternalState(iterator, "_closeParser", false);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(iterator.hasNextValue());
        assertNull(getInternalState(iterator, "_parser"));
    }

    @Test
    public void testHasNextValue_FirstTime_TokenIsNull_NextTokenIsNull() throws IOException {
        setInternalState(iterator, "_hasNextChecked", false);
        setInternalState(iterator, "_closeParser", false);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(null);

        assertFalse(iterator.hasNextValue());
        assertNull(getInternalState(iterator, "_parser"));
    }

    @Test
    public void testHasNextValue_FirstTime_TokenIsNull_NextTokenIsEndArray_WithCloseParser() throws IOException {
        setInternalState(iterator, "_hasNextChecked", false);
        setInternalState(iterator, "_closeParser", true);
        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(iterator.hasNextValue());
        assertNull(getInternalState(iterator, "_parser"));
        verify(mockParser, times(1)).close();
    }

    private Object getInternalState(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }
}
